import { test } from "@e2e/fixtures";
import * as ui from "@e2e/ui-actions";

test.describe("Chat loading indicator", () => {
  test.use({ inspectorOptions: { inspectMode: true } });

  test("Loading dots appear while waiting for bot response, then disappear", async ({
    inspectorPage,
  }) => {
    await test.step("Wait for the welcome turn to finish", async () => {
      await ui.conversationLog.assertions(inspectorPage).agentTurnEndedCountAtLeast(1);
    });

    await test.step("Send message and assert loading dots appear then disappear", async () => {
      const input = ui.inspectorShell.getLocators(inspectorPage).messageInputField;
      const assertions = ui.conversationLog.assertions(inspectorPage);

      await input.fill("What's my balance?");

      const dotsVisible = assertions.loadingDotsVisible();

      await input.press("Enter");
      await dotsVisible;

      await assertions.loadingDotsHidden();
    });
  });
});
